use std::fs

fn parse_int(t: string) -> Option<int> {
    let mut neg = false
    let mut n: int = 0
    let mut count: int = 0
    for c in t.chars() {
        if count == 0 && c == '-' {
            neg = true
        } else if c >= '0' && c <= '9' {
            n = n * 10 + (c as int - '0' as int)
        } else {
            return None
        }
        count += 1
    }
    let digits = if neg { count - 1 } else { count }
    if digits == 0 {
        return None
    }
    if neg { Some(0 - n) } else { Some(n) }
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split(" ") {
        if t == "" {
            continue
        }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop().unwrap_or(0)
            let a = st.pop().unwrap_or(0)
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else {
            match parse_int(t) {
                Some(v) => st.push(v),
                None => return "error: token",
            }
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println(eval(line.trim()))
    }
}

